from lib import *
S = SS('s39')
steps = [
    step("scraper 有一个“待处理响应”的账本:Slot.active_size 累加每个还没处理完的响应的大小,超过 SCRAPER_SLOT_MAX_ACTIVE_SIZE(默认 5,000,000 字节)时 needs_backout() 为真,引擎停止从调度器取新请求。400 个 100 KB 的页面(共 40 MB)、并发 16,回调 await 0.5 s(下载比处理快得多):上限 1,000,000 时峰值 active_size 2,400,312 字节、同时滞留 24 个响应、进程峰值 RSS 99.5 MiB,总耗时 11.1 s;默认 5,000,000 时峰值 6,500,845、65 个响应、118.1 MiB,3.8 s;20,000,000 时 21,202,756、212 个、170.8 MiB,1.3 s;100,000,000(基本不限)时 40,005,200、全部 400 个都滞留、239.4 MiB,0.9 s。上限越小内存越省、总耗时越长。峰值总比上限大一些,因为在途的下载(并发 16 × 100 KB)停不下来。", t=tl(S(1)), mark=lidx(S(1), '默认 5,000,000', '1,000,000'), done=lidx(S(1), '20,000,000', '100,000,000'), b=bars([['上限 1 MB', 99.5, 'RSS 99.5 MiB / 11.1 s'], ['默认 5 MB', 118.1, 'RSS 118.1 MiB / 3.8 s'], ['上限 20 MB', 170.8, 'RSS 170.8 MiB / 1.3 s'], ['基本不限', 239.4, 'RSS 239.4 MiB / 0.9 s']], 239.4, mark=[1], done=[0, 2, 3]), kv=KV([['Slot.active_size', '待处理响应字节数之和'], ['> SCRAPER_SLOT_MAX_ACTIVE_SIZE', '引擎不再取新请求'], ['上限 1 MB → 100 MB', 'RSS 99.5 → 239.4 MiB,耗时 11.1 → 0.9 s'], ['峰值 > 上限', '在途下载还会落进来']], ['Slot.active_size'])),
    step("回调很快(不 await)时没有堆积:同样 400 个 100 KB 页面,峰值 active_size 只有 2,500,325 字节(25 个响应,基本就是并发 16 加一点),进程峰值 RSS 98.2 MiB,总耗时 0.4 s,背压完全没起作用。背压只在“下载快、处理慢”(慢回调、慢 pipeline、慢 item 处理)时才会出现。", t=tl(S(2)), mark=lidx(S(2), '回调不等待'), kv=KV([['回调不等待', '25 个响应、2,500,325 字节、0.4 s'], ['背压', '处理慢于下载时才会触发']], ['回调不等待'])),
    step("小响应也按 1024 字节算(Slot.MIN_RESPONSE_SIZE):6000 个 200 字节的页面、并发 100、回调 await 1 s,默认上限时峰值 active_size 1,047,552 = 1023 × 1024(滞留 1023 个响应),每个响应只有 200 字节也记 1024;把上限降到 500,000,峰值 602,112 = 588 × 1024(588 个响应,500,000 ÷ 1024 ≈ 488 加上在途的下载),RSS 从 258.7 降到 198.2 MiB,总耗时从 11.0 s 变成 13.0 s。默认上限下峰值只到 1023 个,没碰到 5,000,000 ÷ 1024 ≈ 4,883,这里还有别的因素在限制,我没有追到来源。", t=tl(S(3)), mark=lidx(S(3), '500,000'), done=lidx(S(3), '默认 SCRAPER_SLOT_MAX_ACTIVE_SIZE'), kv=KV([['最小计费', '每个响应至少 1024 字节'], ['active_size', '总是 1024 的整数倍(1,047,552 = 1023 × 1024)'], ['上限 500,000', '588 个响应,RSS 198.2 MiB,13.0 s']], ['最小计费'])),
]
A = mkarts('s39', 39, 'Scrapy,背压,SCRAPER_SLOT_MAX_ACTIVE_SIZE,scraper,内存,真实验证,动画演示',
    '实测 scraper 的背压:待处理响应的字节数超过 SCRAPER_SLOT_MAX_ACTIVE_SIZE(默认 5,000,000)引擎就不再取新请求;400 个 100 KB 页面、慢回调下,上限 1 MB → 100 MB 让 RSS 从 99.5 涨到 239.4 MiB、耗时从 11.1 s 降到 0.9 s;快回调没有堆积;小响应按 1024 字节算。',
    '下载很快、处理很慢的时候,Scrapy 会不会把所有响应都堆在内存里?背压在哪里发生、阈值是多少、小响应怎么计?这篇用故意拖慢的回调,量出不同上限下滞留的响应数、内存和耗时。',
    [('5,000,000', 'SCRAPER_SLOT_MAX_ACTIVE_SIZE 的默认值(字节)'), ('99.5 → 239.4 MiB', '上限从 1 MB 放到 100 MB 时进程峰值 RSS'), ('1024', '每个响应在账本里至少计的字节数')],
    [('账本与上限', '<p>响应进入 scraper 时 <code>active_size</code> 加上它的大小(至少 1024),回调、pipeline 处理完才减掉;一超过 <code>SCRAPER_SLOT_MAX_ACTIVE_SIZE</code>,引擎的 <code>needs_backout()</code> 为真,不再取调度器里的请求。上限越大滞留的响应越多、内存越高、总耗时越短。</p>'),
     ('什么时候起作用', '<p>只有处理比下载慢才会堆积;回调、pipeline 都很快时,滞留量基本等于并发数,背压没有效果。</p>'),
     ('小响应', '<p>很小的响应按 1024 字节计费,所以大量小响应时按个数而不是按字节数限制。</p>')],
    steps,
    [ENV_Y + '。服务器立刻返回固定大小的页面;回调是 async def,await asyncio.sleep(…) 模拟慢处理;滞留数与 active_size 在每次 response_received 信号和 5 ms 的定时采样里取最大值;RSS 取 ru_maxrss(进程峰值,macOS 单位是字节)',
     '没有验证:慢 pipeline(而不是慢回调)是否同样占用账本;默认上限下 6000 个小页面只滞留到 1023 个而不是约 4,883 个的原因(没有追到);Linux 上的 RSS 读数;CONCURRENT_ITEMS = 1000 时耗时明显变长(试过一次,77 秒,没有深究);多个 spider 并行时每个 spider 一个账本(源码里是每个 spider 一个 Slot)'],
    '背压')
